def check_training(f,depth,key,history,trace):
    cfg=m.config();counts=np.asarray(m.base.manifest()['supports']['train'],float);w=np.sqrt(counts.sum()/(20*counts));w/=np.dot(counts,w)/counts.sum();parent=m.parent(depth)[2]['train'];teacher=softmax(np.log(np.maximum(parent['probabilities'].astype(float),1e-12))/cfg['self_temperature']).astype(np.float32);labels=parent['labels'];soft=np.eye(20,dtype=np.float32)[labels]*(1-cfg['label_smoothing'])+cfg['label_smoothing']/20
