        for batch,off in enumerate(range(0,3141,16)):
            z=trace[(epoch-1)*197+batch];idx=order[off:off+16];n=len(idx);assert z['local_epoch']==epoch and z['batch']==batch and z['n']==n and z['steps']==197*(epoch-1)+batch+1 and z['alpha_cap']==upper;assert len(z['raw_alpha'])==len(z['ema_alpha'])==depth and all(.4001-1e-7<=v<=upper+1e-7 for v in z['raw_alpha']+z['ema_alpha'])
            rg=np.random.default_rng(np.random.SeedSequence([17,epoch,batch,20261018,40,1]));area=rg.uniform(cfg['crop_area_min'],1,n);ratio=rg.uniform(.9,1.1,n);width=np.minimum(1,np.sqrt(area*ratio));height=np.minimum(1,np.sqrt(area/ratio));crop=np.zeros((n,2,3),np.float32);crop[:,0,0]=width;crop[:,1,1]=height;crop[:,0,2]=rg.uniform(-1,1,n)*(1-width);crop[:,1,2]=rg.uniform(-1,1,n)*(1-height);assert z['crop_SHA256']==m.s.digest(crop)
