            pc,pa,y,q=[arrays[k][sl].astype(float) for k in ('pc','pa','y','teacher_q')];assert np.isfinite(pc).all() and np.isfinite(pa).all() and np.allclose(pc.sum(1),1,atol=2e-6) and np.allclose(pa.sum(1),1,atol=2e-6);parts=loss_parts(pc,pa,y,q,w,cfg)
