def check_last_Adam(f,depth,key,fit,last):
    boundary=torch.load(f/'optimizer_boundary.pt',map_location='cpu',weights_only=False);names=m.names(depth);assert set(boundary['gradients'])==set(names);norm=sum(float(g.double().square().sum()) for g in boundary['gradients'].values())**.5;assert abs(norm-boundary['clip_norm'])<=max(1e-6,1e-5*norm);clip=min(1.,1/(norm+1e-6));maximum=0;epoch=fit['actual_electronic_epochs'];upper=.95+(m.config()['cases'][key]['end_alpha_cap']-.95)*(epoch-1)/7;assert boundary['epoch']==epoch and boundary['alpha_cap']==upper
    for group,ns in zip(boundary['optimizer_before']['param_groups'],boundary['groups']):
        b1,b2=group['betas']
        for pid,n in zip(group['params'],ns):
            before=boundary['optimizer_before']['state'][pid];after=last['optimizer']['state'][pid];assert float(after['step'])==fit['optimizer_steps'];g=boundary['gradients'][n].double()*clip;t=float(before['step'])+1;exp=before['exp_avg'].double()*b1+(1-b1)*g;var=before['exp_avg_sq'].double()*b2+(1-b2)*g.square();raw=boundary['raw_before'][n].double()*(1-group['lr']*group['weight_decay'])-group['lr']*(exp/(1-b1**t))/(var.sqrt()/math.sqrt(1-b2**t)+group['eps'])
            if n.startswith('fusion_logits.'):raw=raw.clamp(.4001,upper)
            maximum=max(maximum,float((raw-last['model'][n].double()).abs().max()));assert torch.allclose(raw,last['model'][n].double(),atol=2e-6,rtol=2e-5) and torch.allclose(exp,after['exp_avg'].double(),atol=1e-7,rtol=2e-5) and torch.allclose(var,after['exp_avg_sq'].double(),atol=1e-7,rtol=2e-5);ema=boundary['ema_before'][n].double()*m.config()['ema_decay']+last['model'][n].double()*(1-m.config()['ema_decay'])
            if n.startswith('fusion_logits.'):ema=ema.clamp(.4001,upper)
            assert torch.allclose(ema,last['ema'][n].double(),atol=2e-7,rtol=1e-6)
    return maximum
